def expected_payloads(close_through):
 designs=json.loads(DESIGNS.read_text());ledger=json.loads(LEDGER.read_text());sequence=json.loads(SEQUENCE.read_text());os=json.loads(OS_PATH.read_text());formats=json.loads(FORMATS.read_text())
 for c in CONFIGS:
  designs["designs"][c["encounter_id"]]=design(c,c["index"]<=close_through)
  ledger["entries"]=[e for e in ledger["entries"] if e["index"]!=c["index"]]
  if c["index"]<=close_through:ledger["entries"].append(ledger_entry(c))
  formats["formats"][c["trainer_id"]].update({"format":"single","target_size":len(c["team"]),"archetype":"Winstrate no-heal attrition","difficulty":round(c["target"]*10),"partner_interaction":False,"level_offset":round(sum(m["level"] for m in c["team"])/len(c["team"]))})
 ledger["entries"].sort(key=lambda e:e["index"])
 next_index=close_through+1
 for e in sequence["entries"]:
  if e["index"]<=close_through:e["status"]="closed"
  elif e["index"]==next_index:e["status"]="next"
  elif e["index"]>next_index:e["status"]="queued"
 next_entry=next(e for e in sequence["entries"] if e["index"]==next_index)
 os["current_state"].update({"closed_encounters":close_through,"next_index":next_index,"next_encounter_id":next_entry["encounter_id"],"queued_sequence_entries":84-close_through-1})
 return designs,ledger,sequence,os,formats
