 for cue in ("nothing held back","Blissey ran out of song","Lurantis gets STRONGER","No guard, no mercy","Four of us"):
  if cue not in scripts:raise SystemExit(f"FAIL: Winstrate dialogue missing {cue}")
 manifest=json.loads(FORMATS.read_text())["formats"]
